                    <label><span>${h(T("STMemoryBooks_Order","Order"))}</span><select id="stmb-topical-clip-entry-order-mode" class="text_pole"><option value="auto">${h(T("STMemoryBooks_ClipReview_ModeAutomatic","Automatic"))}</option><option value="reverse">${h(T("STMemoryBooks_Reverse","Reverse"))}</option><option value="manual">${h(T("STMemoryBooks_Manual","Manual"))}</option></select></label>
